from pathlib import Path
import re
ROOT=Path(__file__).resolve().parent.parent
original=(ROOT/'reference-original.html').read_text()
def section(id): return re.search(r'<section id="'+id+r'">.*?</section>',original,re.S).group()
why=section('why')
services=section('services')
process=re.search(r'<section>\s*<div class="wrap">\s*<div class="section-head">\s*<div class="eyebrow">How It Works.*?</section>',original,re.S).group()
def title(k,h,p): return f'<section class="page-intro"><div class="wrap"><div class="eyebrow">{k}</div><h1>{h}</h1><p>{p}</p></div></section>'
def cta(): return '<section><div class="wrap"><div class="custom-cta"><h2>Your PC. Your way.</h2><p>Start with your games. Fine-tune every detail.</p><a class="btn btn-primary" href="custom-build.html">Start Your Build →</a></div></div></section>'
def cards(): return '<div class="systems-grid" id="systemCards"></div>'
def perf(): return '<section><div class="wrap"><div class="section-head"><div class="eyebrow">Performance</div><h2>Find your next level.</h2><p>Compare illustrative Ultra frame rates across resolutions.</p></div><div id="performanceTable"></div><a class="text-link" href="gaming-pcs.html">Explore the systems →</a></div></section>'
pages={
'index.html':('Home','home','<section class="hero"><div class="wrap hero-layout"><div class="hero-inner"><div class="eyebrow">Precision built. Player focused.</div><h1>Built to Perform.<br>Designed to Dominate.</h1><p>Custom gaming PCs built around your games, your setup, and your budget — hand-assembled, stress-tested, and benchmarked before they reach your desk.</p><div class="hero-btns"><a class="btn btn-primary" href="custom-build.html">Build Your PC →</a><a class="btn btn-outline" href="gaming-pcs.html">View Systems</a></div></div><img class="hero-brand" src="Vertex Logo.png" alt="Vertex Gaming metallic silver and red emblem" width="1254" height="1254"></div></section><section><div class="wrap"><div class="section-head"><div class="eyebrow">Featured Systems</div><h2>Four builds. One standard.</h2><p>Every tier is professionally assembled and benchmarked — the difference is how far you want to push it.</p></div>'+cards()+'</div></section>'+why+perf()+cta()),
'gaming-pcs.html':('Gaming PCs','gaming-pcs',title('The lineup','Find your advantage.','From your first victory to your next obsession. Choose a starting point, then make it yours.')+'<section class="compact"><div class="wrap"><div class="filters" aria-label="Filter by resolution"><button class="filter active" data-filter="all" aria-pressed="true">All systems</button><button class="filter" data-filter="1080p" aria-pressed="false">1080p</button><button class="filter" data-filter="1440p" aria-pressed="false">1440p</button><button class="filter" data-filter="4K" aria-pressed="false">4K</button></div>'+cards()+'<p class="perf-note">Illustrative configurations and prices in USD; final component availability and pricing require confirmation.</p></div></section>'+cta()),
'about.html':('About','about',title('About Vertex','Built with purpose.','Great gaming starts with a system that’s built for you.')+'<section class="compact"><div class="wrap prose"><h2>The details make the difference.</h2><p>Vertex Gaming focuses on performance, clean cable management, and reliable components. Thoughtful cooling and airflow keep every system ready for long sessions, while upgradeable platforms leave room for what comes next.</p><p>We believe a personalized build should combine competitive pricing with professional assembly and testing. Your games, your goals, and your budget guide the build from the first component to the final check.</p></div></section>'+why+process+cta()),
'services.html':('Services','services',title('More than a PC','Keep your setup at its best.','Build something new. Upgrade what you love. Get more from every session.')+services.replace('<h3>','<h3>').replace('</div>\n  </div>\n</section>','</div><p class="service-action"><a class="btn btn-outline" href="support.html">Plan a service request →</a></p></div></section>')+cta()),
'support.html':('Support','support',title('We’re here to help','Let’s get you back in game.','Explore common questions or prepare the details of a support request.')+'''<section class="compact"><div class="wrap support-grid"><div><div class="panel" id="warranty"><h2>Warranty &amp; build support</h2><p>Every new Vertex system includes a 1-year limited warranty for supplied parts and assembly defects, starting on delivery. Keep your invoice and component serial numbers. <a class="inline-link" href="warranty.html">Read full coverage and claim instructions →</a></p></div><div class="panel"><h2>Common questions</h2><details><summary>Can I change a preconfigured system?</summary><p>Yes. Choose Configure System, then change any component in the PC Builder.</p></details><details><summary>Are frame rates guaranteed?</summary><p>No. The figures are illustrative estimates based on the supplied reference, not verified benchmarks. Game settings, drivers, and hardware affect results.</p></details><details><summary>Can I place an order here?</summary><p>This site prepares and confirms builds locally. It does not take payments or transmit orders.</p></details><details><summary>What should I include in a repair request?</summary><p>Include your system specs, the issue, any error messages, and what you have already tried. Never include passwords.</p></details></div></div><form class="panel" id="supportForm"><h2>Prepare a support request</h2><p>Download a request to share with Vertex through your existing contact. This form does not send messages.</p><label for="name">Name</label><input id="name" name="name" required maxlength="100" autocomplete="name"><label for="email">Email</label><input id="email" name="email" type="email" required autocomplete="email"><label for="topic">How can we help?</label><select id="topic" name="topic"><option>Build advice</option><option>PC upgrade</option><option>PC repair</option><option>Performance optimization</option><option>PC cleaning</option><option>Warranty question</option></select><label for="message">Your request</label><textarea id="message" name="message" rows="6" required maxlength="5000"></textarea><button class="btn btn-primary" type="submit">Download request</button><p id="supportStatus" role="status"></p></form></div></section>'''),
'custom-build.html':('PC Builder','custom-build',title('Your next system','Build around your game.','Choose your goals. Dial in the details. See your build come together.')+'''<section class="compact"><div class="wrap"><div class="preset-bar" aria-label="Starting configuration"><span>Start with a system</span><div id="tierPresets"></div></div><div class="builder-layout"><div><div class="panel preview-panel"><div class="preview-head"><div><div class="eyebrow">Live 3D preview</div><h2>Your build, from every angle.</h2></div><span class="preview-badge">Interactive</span></div><div class="build-viewport" id="buildViewport"><img id="previewFallback" src="assets/system.svg" alt="Schematic tower preview" width="600" height="500"><p id="previewStatus" role="status">Loading 3D preview…</p></div><div class="camera-controls" role="group" aria-label="3D camera controls"><button type="button" data-view="front">Front</button><button type="button" data-view="side">Inside</button><button type="button" data-view="rear">Rear</button><button type="button" data-view="top">Top</button><button type="button" data-view="left" aria-label="Rotate camera left">↶</button><button type="button" data-view="right" aria-label="Rotate camera right">↷</button><button type="button" data-view="in" aria-label="Zoom in">+</button><button type="button" data-view="out" aria-label="Zoom out">−</button><button type="button" data-view="reset">Reset view</button><button type="button" id="explodeView" aria-pressed="false">Explode parts</button><button type="button" id="glassView" aria-pressed="true">Glass on</button></div><p class="hint">Drag to orbit · scroll or pinch to zoom · right-drag or two fingers to pan. Focus the viewer and use arrow keys to orbit, +/− to zoom, or R to reset.</p><p class="hint">Schematic 3D models show selected case style, GPU size, RAM sticks, cooling, storage, and lighting. These are not exact manufacturer replicas or a guarantee of fit.</p><p id="previewParts" class="preview-parts" aria-live="polite"></p></div><div class="panel"><div class="step-heading"><span class="p-dot">1</span><h2>Set your target</h2></div><div class="form-grid"><div><label for="resolution">Gaming resolution</label><select id="resolution"><option>1080p</option><option>1440p</option><option>4K</option></select></div><div><label for="goal">Performance goal</label><select id="goal"><option value="60">60 FPS</option><option value="120">120 FPS</option><option value="144">144 FPS</option><option value="240">240 FPS+</option></select></div><div class="full"><label for="budget">Build budget</label><select id="budget"><option value="1000">Under $1,000</option><option value="1500">$1,000–$1,500</option><option value="2000">$1,500–$2,000</option><option value="3000">$2,000–$3,000</option><option value="4500">$3,000–$4,500</option><option value="8000">$4,500–$8,000</option></select></div></div><p class="hint">Changing a target refreshes the recommendation and resets component overrides.</p><fieldset><legend>Your games</legend><div class="games" id="gameChoices"></div></fieldset></div><div class="panel"><div class="step-heading"><span class="p-dot">2</span><h2>Make it yours</h2></div><p id="recommendation"></p><div class="catalog-info"><p>Explore 16 processors, 18 graphics cards, and 10 memory kits.</p><p class="hint">Imported catalog snapshot: July 23, 2025. Historical prices are planning estimates, not live stock or current offers. Other components use Vertex planning allowances. <a href="catalog.html" class="inline-link">Catalog sources &amp; pricing →</a></p></div><div class="form-grid" id="components"></div><p class="hint">The motherboard platform follows your AMD or Intel processor. All memory is DDR5. Exact board BIOS, memory QVL, connectors, and case/cooler fit require a final build review. High-capacity kits may run at lower speeds.</p><button class="btn btn-outline" id="resetBuild">Reset to recommendation</button></div></div><aside class="panel build-summary"><div class="eyebrow">Your configuration</div><h2>Ready for your next level.</h2><div id="liveSummary" aria-live="polite"></div><button class="btn btn-primary" id="reviewBuild">Review Build →</button><p class="hint">Estimate only. No payment required.</p><a class="warranty-link" href="warranty.html">1-year limited parts &amp; labor warranty →</a></aside></div></div></section><dialog id="reviewDialog" aria-labelledby="reviewTitle"><div class="dialog-content"><h2 id="reviewTitle">Review your build</h2><div id="reviewContent"></div><div class="dialog-actions"><button class="btn btn-outline" id="editBuild">Back to editing</button><button class="btn btn-primary" id="confirmBuild">Confirm Build</button></div></div></dialog>''')}
pages['warranty.html']=('Warranty','support',title('Built with confidence','1-year limited warranty.','Straightforward coverage for every new Core, Pro, Ultra, and MAX system.')+"""<section class="compact"><div class="wrap prose warranty-copy"><p class="policy-date">Vertex Gaming · Limited warranty · Effective September 26, 2026</p><h2>What’s covered</h2><p>Vertex Gaming covers defects in the parts it supplies and in its assembly workmanship for one year from the date your new system is delivered or collected. Coverage is included at no additional charge for the original purchaser of a new Vertex system.</p><h2>How we make it right</h2><p>For a covered defect, Vertex will diagnose and repair the system or replace the faulty part with a new or equivalent-function replacement at no charge for covered parts or labor. If a repair or equivalent replacement is not available within a reasonable time, Vertex will offer an appropriate refund for the affected product. Replacement parts remain covered for the balance of the original warranty or 90 days from repair, whichever is longer.</p><h2>What’s excluded</h2><p>This limited warranty does not cover accidental or liquid damage, misuse, improper power, cosmetic wear that does not affect operation, or damage caused by an incompatible upgrade, improper repair, or operation outside component specifications. Software problems, malware, data recovery, and parts not supplied by Vertex are not covered. Opening the case, upgrading a component, or using independent service does not by itself void this warranty; only damage caused by those actions is excluded.</p><h2>Requesting service</h2><ol><li>Contact Vertex using the contact details on your invoice. Provide the order number, delivery date, system serial number, symptoms, and any error messages.</li><li>Vertex will help troubleshoot and, when necessary, arrange a return authorization and service instructions. Do not ship a system before receiving those instructions.</li><li>Back up important files and remove personal accessories before service. Use protective packaging. Service may require reinstalling software; data backup and recovery are not included.</li></ol><p>You pay shipping to Vertex; Vertex pays standard return shipping for a confirmed covered repair to the original delivery country. Any other shipping or non-covered service cost will be quoted for your approval before work begins. Local handoff may be arranged by agreement.</p><h2>Manufacturer warranties &amp; your rights</h2><p>Some components may have separate manufacturer coverage beyond one year. That coverage is subject to the manufacturer’s terms and does not extend Vertex’s labor coverage. This warranty gives you specific legal rights, and you may also have other rights that vary by state or jurisdiction. It does not exclude or limit rights that cannot lawfully be excluded or limited.</p><a class="btn btn-primary" href="support.html?topic=warranty">Prepare a warranty request →</a><p class="hint">The website prepares a downloadable request; it does not send it. Share it through the contact listed on your invoice. A copy of these terms can be requested with your quote or invoice.</p></div></section>""")
pages['catalog.html']=('Catalog sources','gaming-pcs',title('Know your components','An open catalog. Clear estimates.','More brands and models, with transparent sourcing.')+"""<section class="compact"><div class="wrap prose"><h2>Where the models come from</h2><p>The CPU, GPU, and RAM lists are a curated import from <a class="inline-link" href="https://github.com/docyx/pc-part-dataset">Doc Oliver’s PC Part Dataset</a>, an MIT-licensed collection of PCPartPicker catalog data. The source snapshot is dated July 23, 2025. <a class="inline-link" href="assets/catalog/parts.json">View the imported data</a> or <a class="inline-link" href="assets/catalog/LICENSE.txt">read its license</a>.</p><h2>Pricing and availability</h2><p>CPU, graphics, and memory prices are historical snapshot prices rounded to US dollars. Other component prices are Vertex planning allowances. This is not a live retailer inventory: no item is represented as in stock, and no price is a current offer. Final model numbers, prices, and availability are confirmed before an order.</p><h2>Performance and compatibility</h2><p>FPS ranges are illustrative planning estimates, not measured benchmarks. Hardware scores and clearance rules are maintained locally. Minecraft RTX estimates are omitted for non-GeForce selections because this model does not provide a comparable estimate. Final assembly requires checking manufacturer specifications, BIOS support, memory QVL, power connectors, and physical fit.</p><h2>About the 3D preview</h2><p>Locally generated schematic models respond to your choices. The preview shows layout and style, not exact retail-model geometry, cable routing, or a certified fit. It runs locally with Three.js and does not upload your configuration.</p><a class="btn btn-primary" href="custom-build.html">Explore the configurator →</a></div></section>""")
for tier in ['core' ,'pro','ultra','max']:
 pages[f'gaming-pcs/{tier}.html']=(f'Vertex {tier.upper() if tier == "max" else tier.title()}','gaming-pcs',f'<section class="compact"><div class="wrap"><a class="text-link" href="../gaming-pcs.html">← All systems</a><div id="product" data-tier="{tier}"></div></div></section>')
for path,(name,active,body) in pages.items():
 prefix='../' if '/' in path else ''
 nav=''.join(f'<a href="{prefix}{p}.html"'+(' aria-current="page"' if active==p else '')+f'>{n}</a>' for p,n in [('gaming-pcs','Gaming PCs'),('custom-build','Custom Build'),('services','Services'),('about','About'),('support','Support')])
 logo=f'<a class="logo" href="{prefix}index.html"><img src="{prefix}Vertex Logo.png" width="56" height="56" alt=""><span class="brand-name">Vertex <b>Gaming</b></span></a>'
 header=f'<a class="skip-link" href="#main">Skip to content</a><header><nav aria-label="Main navigation">{logo}<div class="nav-links" id="navLinks">{nav}</div><div class="nav-actions"><a class="btn btn-primary" href="{prefix}custom-build.html">Build Your PC</a></div><button class="menu-toggle" id="menuToggle" aria-expanded="false" aria-controls="navLinks" aria-label="Open navigation">☰</button></nav></header>'
 footer=f'<footer><div class="wrap"><div class="foot-top"><div>{logo}<p class="hint">Precision built. Player focused.</p></div><div class="foot-links"><div class="foot-col"><h4>Explore</h4>{nav}</div><div class="foot-col"><h4>Here to help</h4><a href="{prefix}support.html">Support</a><a href="{prefix}warranty.html">Warranty information</a><a href="{prefix}about.html">Our build process</a></div></div></div><div class="foot-bottom"><span>© 2026 Vertex Gaming</span><span class="foot-slogan">Built to Perform. Designed to Dominate.</span></div></div></footer>'
 extra='<script src="assets/vendor/viewer.bundle.js" defer></script>' if path=='custom-build.html' else ''
 html=f'<!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width, initial-scale=1"><meta name="description" content="Vertex Gaming custom gaming PCs. Explore systems and configure a build around your games and budget."><title>{name} | Vertex Gaming</title><link rel="preconnect" href="https://fonts.googleapis.com"><link rel="preconnect" href="https://fonts.gstatic.com" crossorigin><link href="https://fonts.googleapis.com/css2?family=Oxanium:wght@500;600;700;800&family=Inter:wght@400;500;600&display=swap" rel="stylesheet"><link rel="stylesheet" href="{prefix}styles.css"><script src="{prefix}assets/catalog/parts.js" defer></script><script src="{prefix}data.js" defer></script><script src="{prefix}site.js" defer></script>{extra}</head><body data-prefix="{prefix}">{header}<main id="main">{body}</main>{footer}</body></html>'
 (ROOT/path).write_text(html)
(ROOT/'vertex-gaming.html').write_text((ROOT/'index.html').read_text())
print(f'Built {len(pages)} pages and legacy entry point.')
